input.command:
cat > /tmp/setup.sql <<'EOF'
INSTALL spatial; INSTALL httpfs;
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
.timer on
-- quick smoke test: trazo3 row count + schema
SELECT count(*) AS n FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
EOF
timeout 600 duckdb -init /tmp/setup.sql -c "SELECT 1" 2>&1 | head -40

cat > /tmp/init.sql <<'EOF'
INSTALL spatial; INSTALL httpfs;
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
EOF
echo "=== TRAZO3 SCHEMA ==="
timeout 300 duckdb -init /tmp/init.sql -c "DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') LIMIT 1;" 2>&1 | grep -v '^--'

cd /workspace/answers
cat > build_local.sql <<'EOF'
INSTALL spatial; INSTALL httpfs; LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
.timer on
-- input list
CREATE OR REPLACE TABLE list_raw AS
  SELECT * FROM read_csv('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);
-- facilities (small ~40k) - keep geometry as WKB blob for portability
CREATE OR REPLACE TABLE facilities AS
  SELECT entity_id, entity_kind, tier, weight, basis, geom_method, source,
         ST_AsWKB(geometry) AS geom_wkb
  FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
SELECT 'facilities' t, count(*) n FROM facilities;
EOF
timeout 900 duckdb /workspace/answers/work.duckdb -init build_local.sql -c "SELECT 'done'" 2>&1 | grep -v '^--' | grep -v 'Loading'

