input.command:
cd /workspace/answers
timeout 400 duckdb /workspace/answers/work.duckdb -init /tmp/init.sql -csv -c "
-- add real field area in hectares (EPSG:5880) to cand and propagate to fmatch
ALTER TABLE fmatch ADD COLUMN IF NOT EXISTS field_area_ha DOUBLE;
UPDATE fmatch SET field_area_ha = sub.ha FROM (
  SELECT c.Id, ST_Area(ST_Transform(ST_GeomFromWKB(c.geom_wkb),'EPSG:4326','EPSG:5880', always_xy:=true))/10000.0 ha
  FROM cand c
) sub WHERE fmatch.Id = sub.Id;
-- q09
COPY (SELECT count(*)::INT matched_fields FROM fmatch WHERE matched) TO 'q09.csv' (HEADER, DELIMITER ',');
-- q10
COPY (SELECT count(*) FILTER (WHERE pass_single)::INT by_single_parcel_rule,
             count(*) FILTER (WHERE pass_agg AND NOT pass_single)::INT by_aggregate_rule_only
      FROM fmatch) TO 'q10.csv' (HEADER, DELIMITER ',');
-- q11 over matched fields
COPY (SELECT min(max_single_frac) min_single_frac, avg(max_single_frac) avg_single_frac, avg(union_frac) avg_union_frac
      FROM fmatch WHERE matched) TO 'q11.csv' (HEADER, DELIMITER ',');
-- q12
COPY (SELECT count(*) FILTER (WHERE touches_parcel AND NOT matched)::INT n_excluded FROM fmatch) TO 'q12.csv' (HEADER, DELIMITER ',');
-- q13 top 10 cadasters by matched field count
COPY (SELECT primary_cod AS cod_imovel, count(*)::INT n_fields FROM fmatch WHERE matched
      GROUP BY 1 ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10) TO 'q13.csv' (HEADER, DELIMITER ',');
-- q14 total matched-field hectares
COPY (SELECT sum(field_area_ha) matched_field_ha FROM fmatch WHERE matched) TO 'q14.csv' (HEADER, DELIMITER ',');
" 2>&1 | grep -v '^--' | grep -v 'Loading'
for q in q09 q10 q11 q12 q14; do echo "=== $q ==="; cat $q.csv; done
echo "=== q13 ==="; cat q13.csv

